SELECT (SELECT COUNT(*) FROM knowledge




                        AND id IN

                            #{targetId}



                        AND id = ''




       ) AS total,
       (SELECT COUNT(*) FROM document




                        AND knowledge_id IN

                            #{targetId}



                        AND knowledge_id = ''




       ) AS document_count,
       (
           SELECT COUNT(*) FROM document
           WHERE (
               SUBSTRING(reverse(LPAD(COALESCE(status, 'nn0'), 3, 'n')) FROM 1 FOR 1) = '1'
                  OR SUBSTRING(reverse(LPAD(COALESCE(status, 'nn0'), 3, 'n')) FROM 2 FOR 1) = '1'
           )



                       AND knowledge_id IN

                           #{targetId}



                       AND knowledge_id = ''



       ) AS failure_count

SELECT COUNT("id")                          AS customer_added_count,
       create_time :: DATE                  AS "day"
FROM application_chat_user_stats


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= #{query.startTime}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= #{query.endTime}


        AND application_id = #{query.applicationId}


        AND application_id IN (SELECT id FROM application WHERE name LIKE '%' || #{query.name} || '%')




                AND application_id IN

                    #{targetId}



                AND application_id = ''




GROUP BY "day"

