SELECT COALESCE(SUM(message_tokens), 0) + COALESCE(SUM(answer_tokens), 0)
FROM application_chat_record


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= #{query.startTime}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= #{query.endTime}


        AND chat_id IN (SELECT id FROM application_chat WHERE application_id = #{query.applicationId})




                AND chat_id IN (
                    SELECT id FROM application_chat WHERE application_id IN

                        #{targetId}

                )


                AND chat_id IN (SELECT id FROM application_chat WHERE application_id = '')

mapper.sql:
FROM application a
LEFT JOIN application_chat c ON c.application_id = a."id"
LEFT JOIN (
    SELECT chat_id, SUM(message_tokens) + SUM(answer_tokens) AS total_tokens
    FROM application_chat_record
    GROUP BY chat_id
) r ON r.chat_id = c."id"


        AND a.name LIKE '%' || #{query.name} || '%'


        AND TO_CHAR(c.create_time, 'YYYY-MM-DD') >= #{query.startTime}


        AND TO_CHAR(c.create_time, 'YYYY-MM-DD') <= #{query.endTime}




                AND a.id IN

                    #{targetId}



                AND a.id = ''

mapper.select:
SELECT c.chat_user_id, c.chat_user_type, c.asker, COALESCE(SUM(r.message_tokens) + SUM(r.answer_tokens), 0) AS total_tokens, COUNT(r."id") AS chat_record_count FROM application_chat c LEFT JOIN application_chat_record r ON r.chat_id = c."id"
AND TO_CHAR(c.create_time, 'YYYY-MM-DD') >= #{query.startTime}
AND TO_CHAR(c.create_time, 'YYYY-MM-DD') <= #{query.endTime}
AND c.application_id = #{query.applicationId}
AND c.asker ->> 'username' LIKE '%' || #{query.name} || '%'
AND c.application_id IN
#{targetId}
AND c.application_id = ''
GROUP BY c.chat_user_id, c.chat_user_type, c.asker ORDER BY total_tokens DESC

SELECT c.chat_user_id, c.chat_user_type, c.asker, COALESCE(SUM(r.message_tokens) + SUM(r.answer_tokens), 0) AS total_tokens, COUNT(r."id") AS chat_record_count FROM application_chat c LEFT JOIN application_chat_record r ON r.chat_id = c."id"
AND TO_CHAR(c.create_time, 'YYYY-MM-DD') >= #{query.startTime}
AND TO_CHAR(c.create_time, 'YYYY-MM-DD') <= #{query.endTime}
AND c.application_id = #{query.applicationId}
AND c.asker ->> 'username' LIKE '%' || #{query.name} || '%'
AND c.application_id IN
#{targetId}
AND c.application_id = ''
GROUP BY c.chat_user_id, c.chat_user_type, c.asker ORDER BY total_tokens DESC
